const WORDS2=[{"n":151,"w":"achieve","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/əˈtʃiv/","def":"To succeed in doing something.","ex":"You can achieve your goals with practice.","es":"lograr / conseguir","org":"French","ety":"Old French 'achever', literally 'to bring to a head', from 'a chief' - to the chief point. English took it in the 1300s.","triv":"The same 'chief' (head) sits inside mischief, kerchief and chef.","trap":"The -IEVE family: achieve, believe, relieve. I before E, and never a double E.","esn":"Se dice /a-CHIV/: la primera sílaba es débil, casi 'a'."},{"n":152,"w":"advantage","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ədˈvæntɪdʒ/","def":"Something that helps you succeed.","ex":"Speaking English is an advantage at work.","es":"ventaja","org":"French","ety":"From Old French 'avantage', built on 'avant' (before) - being out in front.","triv":"Tennis kept the word in its oldest sense: the player in front has the advantage.","trap":"Ends in -AGE, never -EDGE, and there is only one D.","esn":"Español dice 'ventaja' sin AD-. El inglés sí lo lleva: ADvantage."},{"n":153,"w":"adventure","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ədˈvɛntʃɚ/","def":"An exciting or unusual experience.","ex":"Our camping trip was a real adventure.","es":"aventura","org":"Latin","ety":"Latin 'adventura', 'things about to happen', from 'advenire' (to arrive). It first meant chance or destiny, not excitement.","triv":"An 'adventurer' once meant a merchant who risked money on a voyage.","trap":"-TURE at the end, like nature and future. Keep the D you cannot quite hear.","esn":"En español la D desapareció ('aventura'); en inglés sigue ahí: aDventure."},{"n":154,"w":"advice","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ədˈvaɪs/","def":"Suggestions about what to do.","ex":"My teacher gave me useful advice.","es":"consejo","org":"French","ety":"Old French 'avis', from the phrase 'ce m'est a vis' - 'it seems to me'. The opinion offered became the advice given.","triv":"It is uncountable in English: 'a piece of advice', never 'an advice'.","trap":"advice with C is the noun, advise with S is the verb. Ice is a thing; you advise with an S.","esn":"Truco: la C de advi-C-e es de 'Consejo'; la S de advi-S-e es de 'aconSejar'."},{"n":155,"w":"although","lvl":"Basic","tier":"B1 Intermediate","pos":"conj.","ipa":"/ɔlˈðoʊ/","def":"Despite the fact that.","ex":"Although it was cold, we went outside.","es":"aunque","org":"Old English","ety":"A medieval welding of 'all' and 'though' - originally two words, 'al though'.","triv":"The OUGH here says /oʊ/, one of its seven English pronunciations.","trap":"One L only: AL-though. And the silent GH that OUGH always drags along.","esn":"La GH no suena. Escríbela igual: althouGH."},{"n":156,"w":"appearance","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/əˈpɪrəns/","def":"The way someone or something looks.","ex":"The paint changed the room's appearance.","es":"apariencia","org":"French","ety":"From Old French 'aparoir', from Latin 'apparere' (to come into sight).","triv":"'Keeping up appearances' is recorded in English since the 1700s.","trap":"Double P, and it ends -ANCE, not -ENCE.","esn":""},{"n":157,"w":"appointment","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/əˈpɔɪntmənt/","def":"An arranged meeting at a set time.","ex":"I have an appointment at ten.","es":"cita","org":"French","ety":"Old French 'apointier', to arrange or settle - literally to bring to a point ('point').","triv":"The medical sense is late: for centuries an appointment was a post or office you were given.","trap":"Double P, then -MENT. Two P's, one T in the middle.","esn":""},{"n":158,"w":"arrange","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/əˈreɪndʒ/","def":"To plan or organize something.","ex":"Let's arrange a meeting for Friday.","es":"organizar / arreglar","org":"French","ety":"Old French 'arengier', to put in a row, from 'rang' (rank, row).","triv":"Musical arrangement borrows the same idea: putting the parts in order.","trap":"Double R, and the soft G needs its silent E: arran-GE.","esn":""},{"n":159,"w":"arrival","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/əˈraɪvəl/","def":"The act of reaching a place.","ex":"We waited for the arrival of the train.","es":"llegada","org":"French","ety":"From Old French 'ariver', from Latin 'ad ripam' - to the shore. Every arrival was once a landing.","triv":"'River' is not related, despite the shore inside the etymology.","trap":"Double R, single L, ending -AL.","esn":""},{"n":160,"w":"attention","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/əˈtɛnʃən/","def":"The act of listening or looking carefully.","ex":"Please pay attention to the instructions.","es":"atención","org":"Latin","ety":"Latin 'attendere', to stretch toward - your mind leaning in.","triv":"'Attention!' as a military command dates from the 1700s drill field.","trap":"Double T at the front, then -TION.","esn":"Español 'atención' con una T; el inglés dobla: aTTention."},{"n":161,"w":"available","lvl":"Basic","tier":"B1 Intermediate","pos":"adj.","ipa":"/əˈveɪləbəl/","def":"Ready to be used or obtained.","ex":"Free tickets are available at the desk.","es":"disponible","org":"French","ety":"Built in English from 'avail' (to be of use), from Old French 'valoir', Latin 'valere' - to be worth.","triv":"'To no avail' preserves the old verb almost nobody uses alone anymore.","trap":"One L in the middle: a-VAIL-able. Ends -ABLE, not -IBLE.","esn":""},{"n":162,"w":"average","lvl":"Basic","tier":"B1 Intermediate","pos":"adj.","ipa":"/ˈævərɪdʒ/","def":"Usual or typical.","ex":"An average lesson lasts one hour.","es":"promedio","org":"Arabic","ety":"From Arabic 'awariya' (damaged goods), through Italian 'avaria' and French: the shared loss when cargo was damaged at sea, split among the owners.","triv":"One of the few everyday words that comes from marine insurance law.","trap":"Ends -AGE, and the middle is -ER-, not -AR-.","esn":""},{"n":163,"w":"behave","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/bɪˈheɪv/","def":"To act in a particular way.","ex":"The children behave well in class.","es":"comportarse","org":"Old English","ety":"'Be-' plus 'have' - to have or hold oneself in a certain way.","triv":"Behaviour keeps the U in Britain; American English drops it: behavior.","trap":"One V, and the silent E that makes the A long.","esn":""},{"n":164,"w":"believe","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/bɪˈliv/","def":"To think that something is true.","ex":"I believe your story.","es":"creer","org":"Old English","ety":"Old English 'belyfan', from a Germanic root meaning 'to hold dear'.","triv":"There is a lie hidden in the middle of believe - a spelling mnemonic teachers have used for a century.","trap":"I before E: bel-IEVE. Never believe with EI.","esn":""},{"n":165,"w":"borrow","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/ˈbɑroʊ/","def":"To take something and return it later.","ex":"Can I borrow your pencil?","es":"pedir prestado","org":"Old English","ety":"Old English 'borgian', to lend on pledge - related to 'borough' and 'bargain', all about security given.","triv":"English needs two verbs where Spanish often uses one: you borrow from, you lend to.","trap":"Double R, then -OW.","esn":"borrow = pedir prestado; lend = prestar. No son intercambiables."},{"n":166,"w":"breathe","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/brið/","def":"To take air into and out of your lungs.","ex":"Try to breathe slowly before speaking.","es":"respirar","org":"Old English","ety":"From Old English 'braeth' (vapour, smell). The noun came first; the verb grew its extra E later.","triv":"The noun and the verb are one of English's neatest pairs: breath is short, breathe is long.","trap":"The verb keeps a final E - breathE. The noun 'breath' has none.","esn":"breath /brɛθ/ es sustantivo; breathe /brið/ es verbo. La E final alarga la vocal."},{"n":167,"w":"celebrate","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/ˈsɛləbreɪt/","def":"To do something special for a happy event.","ex":"We will celebrate her birthday tomorrow.","es":"celebrar","org":"Latin","ety":"Latin 'celebrare', to frequent or honour in crowds, from 'celeber' (much-visited, famous).","triv":"'Celebrity' is the same root: a person a crowd gathers around.","trap":"c-e-l-E-BR-ate. The E and the BR are the stumble: never 'celabrate'.","esn":""},{"n":168,"w":"challenge","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ˈtʃælɪndʒ/","def":"A difficult task that tests your ability.","ex":"Learning these words is a fun challenge.","es":"reto / desafío","org":"French","ety":"Old French 'chalenge', from Latin 'calumnia' - a false accusation. A challenge was once a formal charge.","triv":"'Calumny' is the same Latin word borrowed a second time, unchanged.","trap":"Double L, and the ending is -ENGE.","esn":""},{"n":169,"w":"choice","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/tʃɔɪs/","def":"An act of choosing between options.","ex":"You have a choice of two courses.","es":"elección","org":"French","ety":"Old French 'chois', from 'choisir' (to choose), itself from Germanic roots.","triv":"English kept the French noun but the Germanic verb - choose and choice are not from the same family.","trap":"OI in the middle, soft C with a silent E: choi-CE.","esn":""},{"n":170,"w":"comfortable","lvl":"Basic","tier":"B1 Intermediate","pos":"adj.","ipa":"/ˈkʌmftɚbəl/","def":"Physically relaxed and at ease.","ex":"This chair is very comfortable.","es":"cómodo","org":"French","ety":"From Old French 'conforter', Latin 'confortare' - to strengthen greatly. Comfort once meant support, not softness.","triv":"Most Americans say it in three syllables, KUMF-ter-bul, which is why the OR gets lost.","trap":"You cannot hear the OR, but you must write it: comf-OR-table.","esn":""},{"n":171,"w":"communicate","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/kəˈmjunəkeɪt/","def":"To share information or ideas.","ex":"We communicate by email every week.","es":"comunicar","org":"Latin","ety":"Latin 'communicare', to share or make common, from 'communis'.","triv":"Communion, community and communism all grow from that same 'communis'.","trap":"Double M, single N: co-MM-unicate.","esn":"Español una M ('comunicar'); el inglés dobla: coMMunicate."},{"n":172,"w":"compare","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/kəmˈpɛr/","def":"To examine similarities and differences.","ex":"Compare the prices before you buy.","es":"comparar","org":"Latin","ety":"Latin 'comparare', to pair together, from 'par' (equal).","triv":"'Par' survives on the golf course and in 'on a par with'.","trap":"-ARE at the end, and one R only.","esn":""},{"n":173,"w":"competition","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ˌkɑmpəˈtɪʃən/","def":"An event in which people try to win.","ex":"She entered the spelling competition.","es":"competencia / concurso","org":"Latin","ety":"Latin 'competere', to strive together - originally to come together toward one point.","triv":"Competition and competent are the same verb: one strives, the other measures up.","trap":"-TITION, not -TETION. Say com-pe-TI-tion and write what you say.","esn":""},{"n":174,"w":"complain","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/kəmˈpleɪn/","def":"To say that something is wrong.","ex":"Customers sometimes complain about delays.","es":"quejarse","org":"French","ety":"Old French 'complaindre', from Latin 'plangere' - to beat the breast in grief.","triv":"'Plaintiff' and 'plaintive' come from the same beating-the-breast root.","trap":"-AIN at the end, like explain and remain.","esn":""},{"n":175,"w":"complete","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/kəmˈplit/","def":"To finish doing something.","ex":"Please complete the form today.","es":"completo / completar","org":"Latin","ety":"Latin 'complere', to fill up, from 'plenus' (full).","triv":"Complete, comply and compliment were all once the same word about filling a measure.","trap":"-ETE ending, with the silent E doing the work.","esn":""},{"n":176,"w":"confident","lvl":"Basic","tier":"B1 Intermediate","pos":"adj.","ipa":"/ˈkɑnfɪdənt/","def":"Sure of your own ability.","ex":"I feel confident about the test.","es":"seguro de sí mismo","org":"Latin","ety":"Latin 'confidere', to trust fully.","triv":"A confidant (no E) is the person you trust; confident (with E) is how you feel.","trap":"-ENT, not -ANT. Confid-ENT is a feeling.","esn":""},{"n":177,"w":"consider","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/kənˈsɪdɚ/","def":"To think carefully about something.","ex":"Please consider my suggestion.","es":"considerar","org":"Latin","ety":"Latin 'considerare' - possibly to study the stars ('sidus'), the way augurs read the sky before deciding.","triv":"'Desire' may come from the same stargazing family: 'de sidere', from the stars.","trap":"One S, one D: con-SI-der. Never 'concider'.","esn":""},{"n":178,"w":"continue","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/kənˈtɪnju/","def":"To keep doing something.","ex":"We will continue the lesson after lunch.","es":"continuar","org":"Latin","ety":"Latin 'continuare', to join or hold together, from 'tenere' (to hold).","triv":"Continent is the same root: land held together, uninterrupted.","trap":"Ends -UE. Two syllables of vowels at the end: contin-U-E.","esn":""},{"n":179,"w":"decision","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/dɪˈsɪʒən/","def":"A choice made after thinking.","ex":"Choosing this course was a good decision.","es":"decisión","org":"Latin","ety":"Latin 'decidere', to cut off - a decision is where you cut the argument short.","triv":"'Homicide', 'scissors' and 'decide' all share the cutting root -cid-.","trap":"-SION, not -TION. Decide has a D, so decision takes S.","esn":""},{"n":180,"w":"describe","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/dɪˈskraɪb/","def":"To say what something is like.","ex":"Can you describe your hometown?","es":"describir","org":"Latin","ety":"Latin 'describere', to write down, from 'scribere' (to write).","triv":"Script, scripture, subscribe and describe are all the same scribe.","trap":"DE- at the front, never DIS-.","esn":"No es 'discribe'. Piensa en 'DEscribir'."},{"n":181,"w":"develop","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/dɪˈvɛləp/","def":"To grow or become more advanced.","ex":"Reading helps you develop new skills.","es":"desarrollar","org":"French","ety":"Old French 'desveloper', to unwrap - the opposite of 'envelop'.","triv":"Envelope and develop are the same word, one wrapping and one unwrapping.","trap":"No E at the end and no double P: develop.","esn":""},{"n":182,"w":"difference","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ˈdɪfərəns/","def":"A way in which things are not the same.","ex":"What is the difference between these words?","es":"diferencia","org":"Latin","ety":"Latin 'differre', to carry apart, from 'ferre' (to carry).","triv":"The same 'ferre' gives transfer, refer and suffer.","trap":"Double F, then -ERENCE with three E's.","esn":"Español una F; el inglés dobla: diFFerence."},{"n":183,"w":"disappear","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/ˌdɪsəˈpɪr/","def":"To stop being visible.","ex":"The stars disappear when the sun rises.","es":"desaparecer","org":"Latin","ety":"The prefix 'dis-' bolted onto 'appear', which came through French from Latin 'apparere'.","triv":"A useful pair to learn together: one S from dis-, two P's from appear.","trap":"ONE S and TWO P's: dis + appear. The commonest misspelling doubles the wrong letter.","esn":""},{"n":184,"w":"discover","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/dɪˈskʌvɚ/","def":"To find or learn something new.","ex":"You may discover a new hobby.","es":"descubrir","org":"Latin","ety":"Late Latin 'discooperire', to uncover, which reached English through Old French 'descovrir' - to take the cover off something already there.","triv":"That is why you discover a country that was never lost to the people living in it.","trap":"One S, one C: dis-cover. Think of the word 'cover' inside.","esn":""},{"n":185,"w":"education","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ˌɛdʒəˈkeɪʃən/","def":"Learning and teaching knowledge or skills.","ex":"Education can create new opportunities.","es":"educación","org":"Latin","ety":"Latin 'educare', to bring up or rear, close kin to 'educere' - to lead out.","triv":"The 'lead out' sense is why teachers talk about drawing knowledge out of students.","trap":"-CATION ending. The D is followed by U: e-DU-cation.","esn":""},{"n":186,"w":"embarrass","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/ɪmˈbɛrəs/","def":"To make someone feel awkward or ashamed.","ex":"Please do not embarrass me in public.","es":"avergonzar","org":"Spanish","ety":"Spanish 'embarazar' (to obstruct), through French 'embarrasser'. The original sense was to block or hamper.","triv":"It reached English in the 1600s meaning to encumber; the blushing came later.","trap":"Two R's and two S's - the double trouble word: emba-RR-a-SS.","esn":"Falso amigo clásico: 'embarrassed' es avergonzado, NO embarazada (pregnant)."},{"n":187,"w":"encourage","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/ɪnˈkɝɪdʒ/","def":"To give someone support or confidence.","ex":"My friends encourage me to keep trying.","es":"animar","org":"French","ety":"Old French 'encoragier', to put heart into someone, from 'cuer' (heart).","triv":"Courage, encourage and discourage are all about the heart, not the head.","trap":"-OURAGE: the same OUR as in courage.","esn":""},{"n":188,"w":"environment","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ɪnˈvaɪrənmənt/","def":"The natural world around us.","ex":"Recycling helps protect the environment.","es":"medio ambiente","org":"French","ety":"From French 'environner', to surround, from 'viron' (a circuit).","triv":"It only became the word for nature in the 1900s; before that it just meant surroundings.","trap":"The silent N in the middle: enviro-N-ment. Almost nobody pronounces it.","esn":"Se escribe enviroNment aunque casi nadie diga esa N."},{"n":189,"w":"equipment","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ɪˈkwɪpmənt/","def":"The tools needed for an activity.","ex":"The school bought new sports equipment.","es":"equipo","org":"French","ety":"From French 'equiper', to fit out a ship, probably from a Norse word for a crew.","triv":"Uncountable in English: a piece of equipment, never 'an equipment'.","trap":"equip + ment, with no E between them: equipMENT.","esn":""},{"n":190,"w":"especially","lvl":"Basic","tier":"B1 Intermediate","pos":"adv.","ipa":"/ɪˈspɛʃəli/","def":"Particularly; more than usual.","ex":"I enjoy music, especially jazz.","es":"especialmente","org":"Latin","ety":"From Latin 'specialis' (particular), through Old French 'especial'.","triv":"Special and especial are the same word; English kept both and gave them different jobs.","trap":"Starts E-S-P, and ends with double L plus Y: especia-LL-Y.","esn":"El inglés no lleva la E inicial en 'special', pero sí en 'especially'."},{"n":191,"w":"experience","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ɪkˈspɪriəns/","def":"Knowledge or skill gained by doing things.","ex":"She has experience teaching children.","es":"experiencia","org":"Latin","ety":"Latin 'experiri', to try or test - the same root as 'experiment' and 'expert'.","triv":"'Peril' is a distant cousin: trying things has always been risky.","trap":"-IENCE, not -EINCE. And there is an R before it: experi-ENCE.","esn":""},{"n":192,"w":"explain","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/ɪkˈspleɪn/","def":"To make something clear or easy to understand.","ex":"Can you explain this grammar rule?","es":"explicar","org":"Latin","ety":"Latin 'explanare', to make flat or smooth out, from 'planus' (flat).","triv":"Explanation drops the I that explain keeps - one of English's small betrayals.","trap":"-AIN in the verb. Write explanation without that I.","esn":""},{"n":193,"w":"foreign","lvl":"Basic","tier":"B1 Intermediate","pos":"adj.","ipa":"/ˈfɔrən/","def":"From a different country.","ex":"She enjoys watching foreign films.","es":"extranjero","org":"Latin","ety":"Latin 'foras' (outside, out of doors), through Old French 'forain'. A foreigner is simply someone from outside the door.","triv":"The G was inserted by scribes who wrongly thought it belonged, as in 'sovereign'.","trap":"EI, not IE - and a silent G that was never really there.","esn":"La G es muda y la E va antes de la I: fo-rEI-gn."},{"n":194,"w":"friendship","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ˈfrɛndʃɪp/","def":"A relationship between friends.","ex":"Our friendship began at school.","es":"amistad","org":"Old English","ety":"Old English 'freond', originally the present participle of a verb meaning 'to love'.","triv":"A friend is literally 'one who loves'; a fiend was once simply 'one who hates'.","trap":"There is an END in fri-END. Then -SHIP.","esn":""},{"n":195,"w":"furniture","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ˈfɝnɪtʃɚ/","def":"Movable items such as chairs and beds.","ex":"The room needs some new furniture.","es":"muebles","org":"French","ety":"French 'fourniture', a supplying or providing, from 'fournir' (to furnish).","triv":"Uncountable: one piece of furniture, two pieces of furniture - never 'furnitures'.","trap":"-ITURE at the end, the same shape as literature.","esn":"No tiene plural: 'furnitures' no existe."},{"n":196,"w":"generous","lvl":"Basic","tier":"B1 Intermediate","pos":"adj.","ipa":"/ˈdʒɛnərəs/","def":"Willing to give or share.","ex":"Our generous neighbor donated some books.","es":"generoso","org":"Latin","ety":"Latin 'generosus', of noble birth, from 'genus' (stock, family). Generosity was thought to run in the blood.","triv":"Gender, genre, genius and generous all share that 'genus'.","trap":"-OUS ending, with an E in the middle: gen-E-rous.","esn":""},{"n":197,"w":"government","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ˈɡʌvɚnmənt/","def":"The group that runs a country.","ex":"The government plans to build more schools.","es":"gobierno","org":"Greek","ety":"Greek 'kybernan', to steer a ship, borrowed by Latin as 'gubernare' and handed on through Old French 'governer'.","triv":"That Greek steering verb also gives us 'cybernetics', and so 'cyber-' anything.","trap":"The silent N: goverN-ment. Say 'govern' plus 'ment' to keep it.","esn":"La N casi no se oye, pero se escribe: goverNment."},{"n":198,"w":"improve","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/ɪmˈpruv/","def":"To become better or make something better.","ex":"Daily practice can improve your spelling.","es":"mejorar","org":"French","ety":"From Anglo-French 'emprower', to turn to profit, from 'prou' (advantage).","triv":"It meant to make a profit from land long before it meant to make anything better.","trap":"-OVE with a silent E, and only one P.","esn":""},{"n":199,"w":"increase","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/ɪnˈkris/","def":"To become greater in amount or number.","ex":"Exercise can increase your energy.","es":"aumentar","org":"Latin","ety":"Latin 'increscere', to grow into or upon, from 'crescere' (to grow).","triv":"Crescent, crescendo and croissant are all that same growing root.","trap":"-EASE at the end: incr-EASE.","esn":""},{"n":200,"w":"journey","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ˈdʒɝni/","def":"A trip from one place to another.","ex":"The journey took three hours.","es":"viaje","org":"French","ety":"Old French 'journee', a day - specifically a day's travel or a day's work.","triv":"A journeyman was paid by the day, which is why he was not an apprentice or a master.","trap":"J-OUR-NEY: the OUR of 'journal', then -NEY.","esn":""},{"n":201,"w":"knowledge","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ˈnɑlɪdʒ/","def":"Information and understanding you have.","ex":"Books can increase your knowledge.","es":"conocimiento","org":"Old English","ety":"From Old English 'cnawan' (to know) plus a suffix meaning a condition or act.","triv":"The K was pronounced until the 1600s: k-nowledge, k-night, k-nee.","trap":"Silent K at the front, -LEDGE at the end.","esn":"La K no suena. El final suena 'lich' pero se escribe -LEDGE."},{"n":202,"w":"language","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ˈlæŋɡwɪdʒ/","def":"A system of words used to communicate.","ex":"English is a useful language to learn.","es":"idioma / lengua","org":"French","ety":"Old French 'langage', from Latin 'lingua' (tongue).","triv":"Linguist, bilingual and language all come from that one tongue.","trap":"The silent U: lan-GU-age. Without it the G would go soft.","esn":"La U es muda pero obligatoria: lanGUage."},{"n":203,"w":"necessary","lvl":"Basic","tier":"B1 Intermediate","pos":"adj.","ipa":"/ˈnɛsəsɛri/","def":"Needed for a purpose.","ex":"A ticket is necessary to enter.","es":"necesario","org":"Latin","ety":"Latin 'necessarius', from 'necesse' - unavoidable, literally 'not yielding'.","triv":"A 'necessary evil' is recorded in English from the 1500s.","trap":"One C, two S's: ne-C-e-SS-ary.","esn":"Truco inglés: one Collar, two Sleeves - una C y dos S."},{"n":204,"w":"neighbor","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ˈneɪbɚ/","def":"A person who lives near you.","ex":"Our neighbor has a friendly dog.","es":"vecino","org":"Old English","ety":"Old English 'neahgebur' - the near ('neah') dweller ('gebur').","triv":"British English writes neighbour; American English drops the U.","trap":"EI, then the silent GH, then -BOR in American spelling.","esn":"En inglés americano sin U: neighbor, no neighbour."},{"n":205,"w":"opportunity","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/ˌɑpɚˈtunəti/","def":"A chance to do something.","ex":"This course is an opportunity to learn.","es":"oportunidad","org":"Latin","ety":"Latin 'opportunus', from 'ob portum' - toward the harbour. A favourable wind carried you home.","triv":"Its opposite, 'importune', literally means being kept out of the harbour.","trap":"Two P's, one T in the middle: o-PP-or-tunity.","esn":"Español una P; el inglés dobla: oPPortunity."},{"n":206,"w":"organize","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/ˈɔrɡənaɪz/","def":"To plan or put things in order.","ex":"We need to organize the school event.","es":"organizar","org":"Greek","ety":"Greek 'organon', a tool or instrument, through Latin 'organum'.","triv":"The musical organ, bodily organs and organizing a party are all the same instrument.","trap":"American English uses -IZE. The middle is -GAN-, not -GEN-.","esn":""},{"n":207,"w":"patient","lvl":"Basic","tier":"B1 Intermediate","pos":"adj.","ipa":"/ˈpeɪʃənt/","def":"Able to wait calmly.","ex":"Please be patient while I find the file.","es":"paciente","org":"Latin","ety":"Latin 'patiens', suffering or enduring - the same root as 'passion'.","triv":"A hospital patient is literally 'one who suffers', which is why the two senses share a spelling.","trap":"-TIENT, where the TI says /ʃ/: PAY-shunt.","esn":""},{"n":208,"w":"possible","lvl":"Basic","tier":"B1 Intermediate","pos":"adj.","ipa":"/ˈpɑsəbəl/","def":"Able to happen or be done.","ex":"It is possible to learn at any age.","es":"posible","org":"Latin","ety":"Latin 'possibilis', from 'posse' - to be able.","triv":"Power, potent and possible all come from that same 'to be able'.","trap":"Double S, and -IBLE not -ABLE.","esn":"Español una S; el inglés dobla: poSSible."},{"n":209,"w":"receive","lvl":"Basic","tier":"B1 Intermediate","pos":"v.","ipa":"/rɪˈsiv/","def":"To get something that is given or sent.","ex":"You will receive an email tomorrow.","es":"recibir","org":"Latin","ety":"Latin 'recipere', to take back, through Old French 'receivre'.","triv":"Receipt keeps a silent P that was added by scholars to show off the Latin root.","trap":"E before I after C: rec-EI-ve. The classic 'i before e except after c' case.","esn":"Después de C va EI: recEIve."},{"n":210,"w":"responsibility","lvl":"Basic","tier":"B1 Intermediate","pos":"n.","ipa":"/rɪˌspɑnsəˈbɪləti/","def":"A duty to take care of something.","ex":"Feeding the dog is my responsibility.","es":"responsabilidad","org":"Latin","ety":"Latin 'respondere', to answer - a responsible person is one who can answer for something.","triv":"Respond, response, sponsor and spouse all come from that answering root.","trap":"-IBILITY, not -ABILITY. Responsible has an I, so responsibility does too.","esn":"Español 'responsAbilidad'; el inglés lleva I: responsIbility."},{"n":211,"w":"accommodation","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/əˌkɑməˈdeɪʃən/","def":"A place to stay temporarily.","ex":"The course fee includes accommodation.","es":"alojamiento","org":"Latin","ety":"Latin 'accommodare', to make fit, from 'ad-' (to) plus 'commodus' (suitable).","triv":"Often called the most misspelled word in English business writing.","trap":"Two C's and two M's - it accommodates both doubles: a-CC-o-MM-odation.","esn":"Regla: caben dos C y dos M. Español 'acomodación' no dobla nada."},{"n":212,"w":"accurate","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/ˈækjɚət/","def":"Correct and free from mistakes.","ex":"The report contains accurate information.","es":"exacto / preciso","org":"Latin","ety":"Latin 'accuratus', done with care, from 'cura' (care).","triv":"Cure, curious, secure and accurate all grow from that Latin 'care'.","trap":"Double C, then -URATE: a-CC-urate.","esn":""},{"n":213,"w":"acknowledge","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"v.","ipa":"/əkˈnɑlɪdʒ/","def":"To accept or admit that something is true.","ex":"We must acknowledge our mistakes.","es":"reconocer","org":"Old English","ety":"A blend of the old verb 'knowledge' (to confess) with 'acknow', an Old English verb meaning to recognize.","triv":"It is one of the few English words with the letter sequence -CKN-.","trap":"CK then a silent K again: ac-KNOW-ledge. The word 'know' is hiding inside.","esn":"Dentro está 'know': ac-KNOW-ledge."},{"n":214,"w":"acquire","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"v.","ipa":"/əˈkwaɪr/","def":"To gain or obtain something.","ex":"You can acquire new skills through practice.","es":"adquirir","org":"Latin","ety":"Latin 'acquirere', to seek in addition, from 'quaerere' (to seek).","triv":"Query, inquire, question and acquire are all that same seeking verb.","trap":"The silent C before QU: a-C-quire. Same trap as acquaint and acquit.","esn":"Lleva una C muda antes de QU: aCquire."},{"n":215,"w":"additional","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/əˈdɪʃənəl/","def":"Extra; added to what already exists.","ex":"We need additional time to finish.","es":"adicional","org":"Latin","ety":"Latin 'addere', to add, from 'ad-' plus 'dare' (to give).","triv":"Date, donate and addition all come from that Latin 'to give'.","trap":"Double D, then -TIONAL.","esn":""},{"n":216,"w":"adequate","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/ˈædɪkwət/","def":"Enough for a particular need.","ex":"The classroom has adequate lighting.","es":"adecuado / suficiente","org":"Latin","ety":"Latin 'adaequatus', made equal to, from 'aequus' (equal).","triv":"Equal, equator and equity are the same 'aequus'.","trap":"-QUATE at the end, with the E: adeQUATE.","esn":""},{"n":217,"w":"adjust","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"v.","ipa":"/əˈdʒʌst/","def":"To change something slightly to improve it.","ex":"Please adjust the volume.","es":"ajustar","org":"French","ety":"Old French 'ajuster', to make conform, later reshaped by Latin 'iuxta' (near).","triv":"'Just' meaning fair and 'just' meaning barely are both in this word's family tree.","trap":"The D you barely hear: aDjust. Never 'ajust'.","esn":"Español 'ajustar' sin D; el inglés la escribe: aDjust."},{"n":218,"w":"ambition","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/æmˈbɪʃən/","def":"A strong wish to achieve something.","ex":"Her ambition is to become an engineer.","es":"ambición","org":"Latin","ety":"Latin 'ambitio', a going around - from candidates walking the streets of Rome canvassing for votes.","triv":"The same walking-around root gives 'ambient' and 'ambulance'.","trap":"-BITION, with one B and one T: am-BI-tion.","esn":""},{"n":219,"w":"analysis","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/əˈnæləsɪs/","def":"A careful study of something.","ex":"Our analysis revealed several problems.","es":"análisis","org":"Greek","ety":"Greek 'analusis', a loosening or undoing, from 'lyein' (to loosen).","triv":"The plural is Greek too: one analysis, two analyses.","trap":"-YSIS at the end. The plural changes to -YSES.","esn":"Plural irregular: analysis -> analyses."},{"n":220,"w":"apparent","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/əˈpɛrənt/","def":"Easy to see or understand.","ex":"The reason for the delay became apparent.","es":"aparente / evidente","org":"Latin","ety":"Latin 'apparere', to appear or come into sight.","triv":"'Heir apparent' means the heir whose right is plain to see, not merely likely.","trap":"Double P, then -ARENT. There is a PARENT inside ap-PARENT.","esn":""},{"n":221,"w":"approach","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/əˈproʊtʃ/","def":"A way of dealing with something.","ex":"This approach makes learning easier.","es":"acercarse / enfoque","org":"French","ety":"Old French 'aprochier', from Late Latin 'appropiare' - to draw near, from 'prope' (near).","triv":"'Propinquity', a fancy word for nearness, is the same 'prope'.","trap":"Double P, then -OACH, like coach.","esn":""},{"n":222,"w":"appropriate","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/əˈproʊpriət/","def":"Suitable for a particular situation.","ex":"Choose appropriate clothes for the interview.","es":"apropiado","org":"Latin","ety":"Latin 'appropriare', to make one's own, from 'proprius' (own).","triv":"Property, proper and appropriate are the same word about ownership.","trap":"Double P, then -PRIATE: a-PP-ro-PRI-ate.","esn":""},{"n":223,"w":"approval","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/əˈpruvəl/","def":"Official permission or agreement.","ex":"The project needs the director's approval.","es":"aprobación","org":"French","ety":"From Old French 'aprover', from Latin 'approbare' - to assent to as good.","triv":"Probe, prove and approval all come from Latin 'probare', to test.","trap":"Double P, one V, ending -AL.","esn":""},{"n":224,"w":"argument","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/ˈɑrɡjəmənt/","def":"A reason supporting an opinion.","ex":"Her argument convinced the committee.","es":"argumento / discusión","org":"Latin","ety":"Latin 'argumentum', evidence or proof, from 'arguere' (to make clear).","triv":"'Argue' loses its E when it becomes argument - one of the classic exceptions.","trap":"No E after the U: argu-MENT, never 'arguement'.","esn":""},{"n":225,"w":"artificial","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/ˌɑrtəˈfɪʃəl/","def":"Made by people rather than nature.","ex":"The room was decorated with artificial flowers.","es":"artificial","org":"Latin","ety":"Latin 'artificialis', made by art, from 'ars' (skill) plus 'facere' (to make).","triv":"Artifact, artisan and artificial all start from that same 'ars'.","trap":"-FICIAL at the end, with a C: artiFICIAL.","esn":""},{"n":226,"w":"assessment","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/əˈsɛsmənt/","def":"A judgment about ability, quality, or value.","ex":"The assessment includes a speaking task.","es":"evaluación","org":"Latin","ety":"Latin 'assidere', to sit beside - a tax assessor literally sat beside the judge.","triv":"'Assize', 'sedentary' and 'president' all come from that sitting root.","trap":"Double S twice: a-SS-e-SS-ment.","esn":""},{"n":227,"w":"assumption","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/əˈsʌmpʃən/","def":"A belief accepted without proof.","ex":"Our assumption turned out to be wrong.","es":"suposición","org":"Latin","ety":"Latin 'assumere', to take up, from 'sumere' (to take).","triv":"Assume, consume, resume and presume are all the same 'to take'.","trap":"Double S, and the P appears only in the noun: assu-MP-tion.","esn":"El verbo 'assume' no lleva P; el sustantivo sí: assuMPtion."},{"n":228,"w":"atmosphere","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/ˈætməsfɪr/","def":"The mood or feeling of a place.","ex":"The cafe has a relaxed atmosphere.","es":"atmósfera / ambiente","org":"Greek","ety":"Greek 'atmos' (vapour) plus 'sphaira' (ball) - coined in the 1600s for the ball of air around the earth.","triv":"It was invented to describe the moon's air before anyone knew whether it had any.","trap":"-SPHERE at the end, with PH: atmoSPHere.","esn":"El sonido /f/ se escribe PH, como en español 'esfera' con F."},{"n":229,"w":"attempt","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/əˈtɛmpt/","def":"An effort to do something.","ex":"My first attempt was unsuccessful.","es":"intentar / intento","org":"Latin","ety":"Latin 'attemptare', to try or tamper with, from 'temptare' (to test).","triv":"'Tempt' is the same verb: to test someone's resolve.","trap":"Double T at the front and a silent P before the last T: atte-MPT.","esn":"La P casi no se oye: atteMPt."},{"n":230,"w":"authority","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/əˈθɔrəti/","def":"The power to make decisions or give orders.","ex":"The manager has authority to approve changes.","es":"autoridad","org":"Latin","ety":"Latin 'auctoritas', from 'auctor' (originator, author) - the one who causes something to grow.","triv":"Author and authority are the same word; the H was added later by mistaken analogy with Greek.","trap":"-THOR- in the middle: au-THOR-ity, with the author inside.","esn":"Español 'autoridad' sin H; el inglés la lleva: auTHority."},{"n":231,"w":"awareness","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/əˈwɛrnəs/","def":"Knowledge that something exists or matters.","ex":"The campaign raises awareness of pollution.","es":"conciencia","org":"Old English","ety":"Old English 'gewaer', watchful - related to 'wary' and 'ward'.","triv":"Beware is literally 'be wary'.","trap":"aware + ness, keeping the E: awarENESS.","esn":""},{"n":232,"w":"balance","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/ˈbæləns/","def":"A suitable division between different things.","ex":"She maintains a balance between work and rest.","es":"equilibrio / saldo","org":"French","ety":"Old French 'balance', from Latin 'bilanx' - having two ('bi') scale pans ('lanx').","triv":"The two pans are still visible in the zodiac sign Libra, the scales.","trap":"-ANCE at the end, not -ENCE.","esn":""},{"n":233,"w":"beneficial","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/ˌbɛnəˈfɪʃəl/","def":"Helpful or having a good effect.","ex":"Regular exercise is beneficial to your health.","es":"beneficioso","org":"Latin","ety":"Latin 'beneficium', a favour, from 'bene' (well) plus 'facere' (to do).","triv":"Benefit, benevolent and benediction all start with that 'bene'.","trap":"-FICIAL with a C, like official and artificial.","esn":""},{"n":234,"w":"capable","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/ˈkeɪpəbəl/","def":"Having the ability to do something.","ex":"She is capable of leading the team.","es":"capaz","org":"French","ety":"From Late Latin 'capabilis', able to hold, from 'capere' (to take).","triv":"Capacity, capture and capable all come from that taking verb.","trap":"-ABLE, not -IBLE. One P.","esn":""},{"n":235,"w":"circumstance","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/ˈsɝkəmstæns/","def":"A fact or condition affecting a situation.","ex":"Illness was a circumstance we had not expected.","es":"circunstancia","org":"Latin","ety":"Latin 'circumstantia' - what stands ('stare') around ('circum') you.","triv":"'Pomp and Circumstance' takes its title from Othello.","trap":"CIRCUM- with a U, then -STANCE.","esn":"Español 'circuNstancia' con N; el inglés lleva M: circuMstance."},{"n":236,"w":"commitment","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/kəˈmɪtmənt/","def":"Willingness to give time and effort.","ex":"Learning a language requires commitment.","es":"compromiso","org":"Latin","ety":"Latin 'committere', to join or entrust, from 'mittere' (to send).","triv":"Mission, admit, permit and commitment all come from that sending verb.","trap":"Double M, then ONE T: commit + ment = commitMENT, not 'committment'.","esn":""},{"n":237,"w":"complexity","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/kəmˈplɛksəti/","def":"The state of having many connected parts.","ex":"We underestimated the complexity of the task.","es":"complejidad","org":"Latin","ety":"Latin 'complexus', embracing or encircling, from 'plectere' (to weave).","triv":"Perplexed and complexity are woven from the same thread.","trap":"-EXITY at the end: comple-XITY.","esn":""},{"n":238,"w":"comprehensive","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/ˌkɑmprɪˈhɛnsɪv/","def":"Including all or nearly all important details.","ex":"The teacher gave a comprehensive explanation.","es":"completo / exhaustivo","org":"Latin","ety":"Latin 'comprehendere', to grasp entirely, from 'prehendere' (to seize).","triv":"In British schooling a 'comprehensive' is a school that takes all abilities.","trap":"-HEN- in the middle: compre-HEN-sive.","esn":"Ojo: no significa 'comprensivo' (understanding); significa completo."},{"n":239,"w":"considerable","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/kənˈsɪdərəbəl/","def":"Large in amount or importance.","ex":"The repairs took considerable time.","es":"considerable","org":"Latin","ety":"From Latin 'considerare' - worth considering, and so large enough to be worth it.","triv":"The leap from 'worth thinking about' to 'big' happened in the 1600s.","trap":"-ABLE here, though 'responsible' takes -IBLE. No rule will save you: learn the pair.","esn":""},{"n":240,"w":"consistent","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/kənˈsɪstənt/","def":"Staying at a similar standard over time.","ex":"Her consistent effort led to steady progress.","es":"coherente / constante","org":"Latin","ety":"Latin 'consistere', to stand firm together, from 'sistere' (to stand).","triv":"Assist, resist and consistent all stand on that same root.","trap":"-ENT at the end, and -SIST- in the middle.","esn":""},{"n":241,"w":"contribution","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/ˌkɑntrɪˈbjuʃən/","def":"Something given to help a shared effort.","ex":"Your contribution made the event possible.","es":"contribución / aportación","org":"Latin","ety":"Latin 'contribuere', to bring together, from 'tribuere' (to grant) - originally to divide among the tribes.","triv":"Tribute, tribune and tribe all come from that same Roman division.","trap":"-BUTION at the end: contri-BU-tion.","esn":""},{"n":242,"w":"convince","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"v.","ipa":"/kənˈvɪns/","def":"To make someone believe or agree.","ex":"The evidence may convince them to act.","es":"convencer","org":"Latin","ety":"Latin 'convincere', to overcome decisively, from 'vincere' (to conquer).","triv":"'Veni, vidi, vici' - the 'vici' there is the same verb.","trap":"-INCE at the end, soft C: convin-CE.","esn":""},{"n":243,"w":"consequence","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/ˈkɑnsəkwɛns/","def":"A result of an action or situation.","ex":"One consequence of the storm was flooding.","es":"consecuencia","org":"Latin","ety":"Latin 'consequi', to follow closely, from 'sequi' (to follow).","triv":"Sequence, sequel and consequence all follow that same verb.","trap":"-QUENCE at the end, with QU: conse-QUENCE.","esn":"Español 'consecuencia' con C; el inglés usa QU: conseQUence."},{"n":244,"w":"controversial","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/ˌkɑntrəˈvɝʃəl/","def":"Causing strong disagreement.","ex":"The proposal was highly controversial.","es":"polémico","org":"Latin","ety":"Latin 'controversus', turned against, from 'contra' (against) plus 'vertere' (to turn).","triv":"Version, convert and controversial all turn on that same 'vertere'.","trap":"-VERSIAL at the end, with an S: contro-VER-SIAL.","esn":""},{"n":245,"w":"convenient","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/kənˈvinjənt/","def":"Easy or suitable for your needs.","ex":"Online classes are convenient for many students.","es":"conveniente / práctico","org":"Latin","ety":"Latin 'convenire', to come together or agree, from 'venire' (to come).","triv":"Convent, convention and convenient are all about coming together.","trap":"-IENT at the end, not -IANT.","esn":""},{"n":246,"w":"cooperate","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"v.","ipa":"/koʊˈɑpəreɪt/","def":"To work together for a shared purpose.","ex":"The two schools agreed to cooperate.","es":"cooperar","org":"Latin","ety":"Latin 'cooperari', to work together, from 'operari' (to work).","triv":"Modern American style drops the old diaeresis: coöperate became cooperate.","trap":"Double O at the front, no hyphen: CO-O-perate.","esn":""},{"n":247,"w":"crucial","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/ˈkruʃəl/","def":"Extremely important to the result.","ex":"Clear communication is crucial to success.","es":"crucial / decisivo","org":"Latin","ety":"Latin 'crux' (cross) - Francis Bacon's 'instantia crucis' was a crossroads experiment that decided which way to go.","triv":"Crux, crusade, crucify and crucial all stand on that cross.","trap":"-CIAL at the end, with a C: cru-CIAL.","esn":""},{"n":248,"w":"curiosity","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/ˌkjʊriˈɑsəti/","def":"A strong wish to learn or know.","ex":"The experiment sparked the children's curiosity.","es":"curiosidad","org":"Latin","ety":"Latin 'curiosus', careful or inquisitive, from 'cura' (care).","triv":"A 'curiosity shop' sold odd objects long before the word meant the urge to know.","trap":"-IOSITY at the end: cur-I-OS-ity.","esn":""},{"n":249,"w":"demonstrate","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"v.","ipa":"/ˈdɛmənstreɪt/","def":"To show clearly how something works.","ex":"The instructor will demonstrate the technique.","es":"demostrar","org":"Latin","ety":"Latin 'demonstrare', to point out, from 'monstrare' (to show).","triv":"'Monster' is related: a monster was originally an omen, something shown as a warning.","trap":"-MONSTR- in the middle: de-MONSTR-ate, with a monster inside.","esn":""},{"n":250,"w":"determination","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/dɪˌtɝməˈneɪʃən/","def":"The will to keep trying despite difficulty.","ex":"Her determination helped her finish the race.","es":"determinación","org":"Latin","ety":"Latin 'determinare', to set limits to, from 'terminus' (boundary).","triv":"Terminal, terminate and determination all come from that boundary stone.","trap":"-TERMIN- in the middle, then -ATION.","esn":""},{"n":251,"w":"distinguish","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"v.","ipa":"/dɪˈstɪŋɡwɪʃ/","def":"To recognize the difference between things.","ex":"Can you distinguish fact from opinion?","es":"distinguir","org":"Latin","ety":"Latin 'distinguere', to separate by pricking or marking.","triv":"'Extinguish' looks related but is a different verb entirely.","trap":"-GUISH at the end, with the silent U: distin-GU-ish.","esn":"La U es muda: distinGUish."},{"n":252,"w":"efficient","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/ɪˈfɪʃənt/","def":"Working well with little waste.","ex":"The new system is more efficient.","es":"eficiente","org":"Latin","ety":"Latin 'efficere', to accomplish, from 'facere' (to make).","triv":"Effect, efficacy and efficient are all about getting something made.","trap":"Double F, then -CIENT: e-FF-i-CIENT.","esn":"Español una F; el inglés dobla: eFFicient."},{"n":253,"w":"emphasize","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"v.","ipa":"/ˈɛmfəsaɪz/","def":"To give special importance to something.","ex":"The teacher will emphasize the main points.","es":"enfatizar / subrayar","org":"Greek","ety":"Greek 'emphasis', an appearing or showing forth, from 'phainein' (to show).","triv":"Phantom, phase and emphasize all come from that Greek showing.","trap":"PH for the /f/ sound, then -SIZE in American spelling.","esn":"El sonido /f/ va con PH: emPHasize."},{"n":254,"w":"encounter","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"v.","ipa":"/ɪnˈkaʊntɚ/","def":"To meet or experience unexpectedly.","ex":"You may encounter some technical problems.","es":"encuentro / encontrarse con","org":"French","ety":"Old French 'encontrer', from Late Latin 'incontra' - to meet face to face, literally 'in front of'.","triv":"It meant a hostile meeting for centuries; the neutral sense is newer.","trap":"-COUNTER at the end: the whole word 'counter' is inside it.","esn":""},{"n":255,"w":"essential","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/ɪˈsɛnʃəl/","def":"Completely necessary.","ex":"Clean water is essential for life.","es":"esencial / imprescindible","org":"Latin","ety":"Latin 'essentia', being or essence, from 'esse' (to be).","triv":"Coined by Roman writers struggling to translate Greek philosophy.","trap":"Double S, then -TIAL: e-SS-en-TIAL.","esn":"Español una S; el inglés dobla: eSSential."},{"n":256,"w":"estimate","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"v.","ipa":"/ˈɛstəmeɪt/","def":"To judge an amount approximately.","ex":"We estimate that the work will take a week.","es":"estimar / presupuesto","org":"Latin","ety":"Latin 'aestimare', to value or appraise.","triv":"'Esteem' is the same verb borrowed through French - to value a person instead of a thing.","trap":"-IMATE at the end: est-I-mate.","esn":""},{"n":257,"w":"evaluate","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"v.","ipa":"/ɪˈvæljueɪt/","def":"To judge the quality or value of something.","ex":"Teachers evaluate students' progress regularly.","es":"evaluar","org":"French","ety":"French 'evaluer', from 'value' - to work out the worth of something.","triv":"It is a late arrival, borrowed only in the 1800s.","trap":"-ALUATE at the end: ev-ALU-ate, with the U.","esn":""},{"n":258,"w":"evidence","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/ˈɛvɪdəns/","def":"Facts or information supporting a belief.","ex":"There is no evidence to support that claim.","es":"pruebas / evidencia","org":"Latin","ety":"Latin 'evidentia', clearness, from 'videre' (to see) - what is plainly seen.","triv":"Vision, video, view and evidence all come from that Latin seeing.","trap":"-ENCE at the end, not -ANCE.","esn":"Ojo: 'evidence' suele ser 'pruebas', no solo 'evidencia'."},{"n":259,"w":"exception","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/ɪkˈsɛpʃən/","def":"Something that does not follow a rule.","ex":"This spelling is an exception to the rule.","es":"excepción","org":"Latin","ety":"Latin 'excipere', to take out, from 'capere' (to take).","triv":"'The exception proves the rule' originally meant it tests the rule, not confirms it.","trap":"-CEPTION at the end, with the C: ex-CEP-tion.","esn":""},{"n":260,"w":"existence","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/ɪɡˈzɪstəns/","def":"The state of being real or present.","ex":"Scientists study the existence of life elsewhere.","es":"existencia","org":"Latin","ety":"Latin 'existere', to step out or emerge, from 'sistere' (to stand).","triv":"Existentialism took its name from this verb in the 1940s.","trap":"-ENCE at the end, not -ANCE: exist-ENCE.","esn":""},{"n":261,"w":"expectation","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/ˌɛkspɛkˈteɪʃən/","def":"A belief about what will happen.","ex":"My expectation was that the test would be easy.","es":"expectativa","org":"Latin","ety":"Latin 'expectare', to look out for, from 'spectare' (to watch).","triv":"Spectator, inspect and expectation are all watching words.","trap":"-PECT- in the middle, then -ATION.","esn":""},{"n":262,"w":"explanation","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/ˌɛkspləˈneɪʃən/","def":"Details that make something understandable.","ex":"Her explanation helped us understand the problem.","es":"explicación","org":"Latin","ety":"Latin 'explanare', to make flat or plain, from 'planus' (flat).","triv":"Explain and explanation split apart in the 1500s and never lined up again.","trap":"No I here, though explain has one: explAnation, not 'explaination'.","esn":"explain lleva I, explanation NO: expl-A-nation."},{"n":263,"w":"flexible","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/ˈflɛksəbəl/","def":"Able to change to suit new conditions.","ex":"We need a flexible schedule.","es":"flexible","org":"Latin","ety":"Latin 'flexibilis', from 'flectere' (to bend).","triv":"Reflect, deflect and flexible all bend the same way.","trap":"-IBLE, not -ABLE.","esn":""},{"n":264,"w":"furthermore","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adv.","ipa":"/ˌfɝðɚˈmɔr/","def":"In addition to what has been said.","ex":"The course is practical; furthermore, it is affordable.","es":"además","org":"Old English","ety":"A compound of 'further' and 'more', both Old English, welded together in the 1300s.","triv":"'Further' and 'farther' were the same word until modern editors split their duties.","trap":"One word, with the TH: fur-THER-more.","esn":""},{"n":265,"w":"guarantee","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"v.","ipa":"/ˌɡɛrənˈti/","def":"To promise that something will happen.","ex":"We cannot guarantee that it will arrive today.","es":"garantía / garantizar","org":"French","ety":"Old French 'garant', a warrant or protector - a Germanic word that arrived through French.","triv":"Warrant and guarantee are the same word, one keeping the W and the other the G.","trap":"GUA- at the front and double E at the end: GUARantEE.","esn":"Empieza como 'guante': GUA-. Y termina en doble E."},{"n":266,"w":"hesitation","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/ˌhɛzəˈteɪʃən/","def":"A pause caused by uncertainty.","ex":"She accepted the invitation without hesitation.","es":"vacilación / duda","org":"Latin","ety":"Latin 'haesitare', to stick fast or stammer, from 'haerere' (to stick).","triv":"'Adhere' and 'hesitation' both come from that sticking verb.","trap":"-SITATION: he-SI-ta-tion, with an S, not a Z.","esn":""},{"n":267,"w":"identity","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"n.","ipa":"/aɪˈdɛntəti/","def":"The qualities or facts that define who you are.","ex":"Your passport confirms your identity.","es":"identidad","org":"Latin","ety":"Late Latin 'identitas', from 'idem' (the same).","triv":"'Idem' still appears in footnotes meaning 'the same source'.","trap":"-ENTITY at the end: id-ENTITY, with the whole word 'entity' inside.","esn":""},{"n":268,"w":"illustrate","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"v.","ipa":"/ˈɪləstreɪt/","def":"To explain by using examples or pictures.","ex":"These diagrams illustrate the process.","es":"ilustrar","org":"Latin","ety":"Latin 'illustrare', to light up, from 'lustrare' (to make bright).","triv":"Lustre, illustrious and illustrate all shine from that root.","trap":"Double L at the front: i-LL-ustrate.","esn":"Español una L; el inglés dobla: iLLustrate."},{"n":269,"w":"independent","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/ˌɪndɪˈpɛndənt/","def":"Able to act without relying on others.","ex":"The course helps students become independent learners.","es":"independiente","org":"Latin","ety":"'In-' (not) plus 'dependent', from Latin 'dependere' - to hang from.","triv":"A dependent hangs from someone; an independent hangs from no one.","trap":"-ENT at the end, and every vowel in the middle is an E: ind-E-p-E-nd-E-nt.","esn":"Tres E: indEpEndEnt. En español hay una I final; en inglés no."},{"n":270,"w":"inevitable","lvl":"Intermediate","tier":"B2 Upper Intermediate","pos":"adj.","ipa":"/ɪnˈɛvɪtəbəl/","def":"Certain to happen; impossible to avoid.","ex":"Some changes are inevitable.","es":"inevitable","org":"Latin","ety":"Latin 'inevitabilis', from 'evitare' (to avoid) - what cannot be avoided.","triv":"'Vitiate' and 'evitable' come from the same avoiding verb, but nobody uses evitable.","trap":"-ITABLE at the end: inev-ITABLE, and -ABLE not -IBLE.","esn":""},{"n":271,"w":"acquaintance","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/əˈkweɪntəns/","def":"Someone you know, but not closely.","ex":"An acquaintance told me about the course.","es":"conocido / conocimiento","org":"French","ety":"Old French 'acointance', from 'acointier' - to make known, from Latin 'cognoscere' (to know).","triv":"'Auld Lang Syne' asks whether old acquaintance should be forgot - the word has been in that song since 1788.","trap":"The silent C before QU, then -TANCE: a-C-quain-TANCE.","esn":"C muda antes de QU, como en acquire: aCquaintance."},{"n":272,"w":"allegiance","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/əˈlidʒəns/","def":"Loyalty to a person, group, or country.","ex":"The players showed allegiance to their team.","es":"lealtad","org":"French","ety":"Old French 'ligeance', the duty of a liege man to his lord, with the A- added in English.","triv":"'Liege' survives almost nowhere else in modern English.","trap":"Double L, then -EGIANCE with a G: a-LL-e-GIANCE.","esn":""},{"n":273,"w":"amendment","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/əˈmɛndmənt/","def":"A formal change to a document or rule.","ex":"The committee approved an amendment to the rules.","es":"enmienda","org":"French","ety":"Old French 'amender', from Latin 'emendare' - to free from fault, from 'menda' (a flaw).","triv":"'Mend' is the same word with its front worn off.","trap":"One M in the middle, then -DMENT: amen-DMENT.","esn":""},{"n":274,"w":"anonymity","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˌænəˈnɪməti/","def":"The state of having your identity unknown.","ex":"The survey protects each participant's anonymity.","es":"anonimato","org":"Greek","ety":"Greek 'anonymos', nameless, from 'an-' (without) plus 'onyma' (name).","triv":"Synonym, pseudonym and anonymity all come from that Greek 'name'.","trap":"-NYMITY at the end, with a Y: anon-Y-mity.","esn":"El sonido /i/ se escribe con Y: anonYmity."},{"n":275,"w":"apprehension","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˌæprɪˈhɛnʃən/","def":"Worry about something that may happen.","ex":"She felt apprehension before the interview.","es":"aprensión / temor","org":"Latin","ety":"Latin 'apprehendere', to seize - fear grabs hold of you, and so does an idea you grasp.","triv":"That is why police 'apprehend' a suspect and students 'comprehend' a lesson.","trap":"Double P, then -HENSION: a-PP-re-HEN-sion.","esn":""},{"n":276,"w":"bureaucracy","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/bjʊˈrɑkrəsi/","def":"An administrative system with complex rules.","ex":"Excessive bureaucracy delayed the application.","es":"burocracia","org":"French","ety":"French 'bureau' (desk, originally the cloth covering it) plus Greek '-kratia' (rule) - government by desk.","triv":"Coined in 1700s France as a joke about officials, and it never stopped being one.","trap":"-EAU- in the middle and -CRACY at the end: bur-EAU-CRACY.","esn":"El grupo francés EAU suena /o/: bureau."},{"n":277,"w":"catastrophe","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/kəˈtæstrəfi/","def":"An event causing great damage or suffering.","ex":"The earthquake was a national catastrophe.","es":"catástrofe","org":"Greek","ety":"Greek 'katastrophe', an overturning, from 'strephein' (to turn) - the turn at the end of a tragedy.","triv":"In Greek drama it was simply the final act, disastrous or not.","trap":"-PHE at the end, and the final E is pronounced: ka-TAS-tro-fee.","esn":"La E final sí se pronuncia: /kəˈtæstrəfi/."},{"n":278,"w":"coincidence","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/koʊˈɪnsɪdəns/","def":"An unexpected connection that happens by chance.","ex":"Meeting you on the same flight was a coincidence.","es":"coincidencia","org":"Latin","ety":"Latin 'coincidere', to fall upon together, from 'cadere' (to fall).","triv":"Accident, incident and coincidence are all things that fall out.","trap":"-CIDENCE at the end, and no hyphen after CO.","esn":""},{"n":279,"w":"collaboration","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/kəˌlæbəˈreɪʃən/","def":"The act of working together on something.","ex":"The project requires collaboration across departments.","es":"colaboración","org":"Latin","ety":"Latin 'collaborare', to work with, from 'laborare' (to labour).","triv":"'Collaborator' picked up its dark wartime sense only in the 1940s.","trap":"Double L, single B: co-LL-a-B-oration.","esn":"Español una L; el inglés dobla: coLLaboration."},{"n":280,"w":"commemorate","lvl":"Advanced","tier":"Advanced Challenge","pos":"v.","ipa":"/kəˈmɛməreɪt/","def":"To honor the memory of a person or event.","ex":"The ceremony will commemorate the school's founder.","es":"conmemorar","org":"Latin","ety":"Latin 'commemorare', to call to mind together, from 'memor' (mindful).","triv":"Memory, memorial and commemorate all keep that same mindfulness.","trap":"Double M at the front, single M after: co-MM-e-M-orate.","esn":"Español 'coNmemorar' con N; el inglés lleva doble M: coMMemorate."},{"n":281,"w":"compassion","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/kəmˈpæʃən/","def":"Concern for suffering and a wish to help.","ex":"The volunteers treated everyone with compassion.","es":"compasión","org":"Latin","ety":"Late Latin 'compassio', a suffering with, from 'pati' (to suffer) - a literal translation of Greek 'sympatheia'.","triv":"Patient, passion and compassion all come from that suffering verb.","trap":"Double S before -ION: compa-SS-ion.","esn":"Español una S; el inglés dobla: compaSSion."},{"n":282,"w":"conscientious","lvl":"Advanced","tier":"Advanced Challenge","pos":"adj.","ipa":"/ˌkɑnʃiˈɛnʃəs/","def":"Careful and responsible about doing things well.","ex":"A conscientious editor checks every detail.","es":"concienzudo","org":"Latin","ety":"Latin 'conscientia', knowledge within oneself, from 'scire' (to know).","triv":"'Conscientious objector' entered English during the First World War.","trap":"SCI in the middle and -TIOUS at the end: con-SCI-en-TIOUS.","esn":"Dos grupos difíciles: SCI y -TIOUS."},{"n":283,"w":"consensus","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/kənˈsɛnsəs/","def":"General agreement within a group.","ex":"The team reached a consensus on the design.","es":"consenso","org":"Latin","ety":"Latin 'consensus', agreement, from 'consentire' - to feel together.","triv":"'Consensus of opinion' is a tautology editors have been striking out for a century.","trap":"All S's, no C in the middle: con-S-en-S-us. Not 'concensus'.","esn":""},{"n":284,"w":"credibility","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˌkrɛdəˈbɪləti/","def":"The quality of being believable or trustworthy.","ex":"Reliable sources give the report credibility.","es":"credibilidad","org":"Latin","ety":"Latin 'credibilis', worthy of belief, from 'credere' (to believe).","triv":"Credit, creed and credibility all rest on that believing.","trap":"-IBILITY, not -ABILITY: cred-IBILITY.","esn":""},{"n":285,"w":"deteriorate","lvl":"Advanced","tier":"Advanced Challenge","pos":"v.","ipa":"/dɪˈtɪriəreɪt/","def":"To become worse in condition or quality.","ex":"The empty building began to deteriorate.","es":"deteriorarse","org":"Latin","ety":"Late Latin 'deteriorare', from 'deterior' (worse).","triv":"There is no positive counterpart: English never borrowed 'meliorate' with the same success.","trap":"Two I's and three O's in sequence: de-TER-I-OR-ate. Say all five syllables.","esn":"Cinco sílabas: de-te-ri-o-rate. Si las dices todas, la escribes bien."},{"n":286,"w":"discrepancy","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/dɪˈskrɛpənsi/","def":"A difference between things that should agree.","ex":"We found a discrepancy between the two totals.","es":"discrepancia","org":"Latin","ety":"Latin 'discrepare', to sound differently, from 'crepare' (to rattle or creak).","triv":"The image is two instruments out of tune with each other.","trap":"-ANCY at the end, not -ENCY: discrep-ANCY.","esn":""},{"n":287,"w":"discrimination","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/dɪˌskrɪməˈneɪʃən/","def":"Unfair treatment based on a group characteristic.","ex":"The policy aims to prevent discrimination at work.","es":"discriminación","org":"Latin","ety":"Latin 'discriminare', to divide or distinguish, from 'crimen' (a judgement or charge).","triv":"It meant simply 'telling things apart' until the 1800s gave it its social meaning.","trap":"One S, then -CRIMIN-: di-S-crimination.","esn":""},{"n":288,"w":"ecological","lvl":"Advanced","tier":"Advanced Challenge","pos":"adj.","ipa":"/ˌikəˈlɑdʒɪkəl/","def":"Relating to living things and their environment.","ex":"The team studied the dam's ecological impact.","es":"ecológico","org":"Greek","ety":"Greek 'oikos' (house) plus '-logia' (study) - coined in German in 1866 as the study of the household of nature.","triv":"Economy shares that same 'oikos': the management of the house.","trap":"ECO- at the front, then -LOGICAL, with no extra A.","esn":""},{"n":289,"w":"eligibility","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˌɛlɪdʒəˈbɪləti/","def":"The state of meeting the required conditions.","ex":"Check your eligibility before applying for the grant.","es":"elegibilidad","org":"Latin","ety":"Latin 'eligere', to pick out, from 'legere' (to choose).","triv":"Elect, elite and eligibility all come from that choosing verb.","trap":"-IBILITY again, and a G that sounds like J: eli-G-ibility.","esn":""},{"n":290,"w":"entrepreneur","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˌɑntrəprəˈnɝ/","def":"Someone who starts a business and takes risks.","ex":"The entrepreneur opened a small language school.","es":"emprendedor","org":"French","ety":"French 'entreprendre', to undertake - borrowed whole, spelling and all, in the 1800s.","triv":"English has no native word for it, which is why the French one stuck.","trap":"-PRENEUR at the end: entre-PRE-NEUR. Three French vowel clusters in a row.","esn":"Palabra francesa entera. Termina -EUR, no -OR."},{"n":291,"w":"equilibrium","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˌikwəˈlɪbriəm/","def":"A state in which opposing forces are balanced.","ex":"The system gradually returned to equilibrium.","es":"equilibrio","org":"Latin","ety":"Latin 'aequilibrium', from 'aequus' (equal) plus 'libra' (balance, scales).","triv":"'Libra' is still the sign of the scales, and the pound sign is an L for the same reason.","trap":"-LIBRIUM at the end, with an I: equi-LIB-ri-um.","esn":""},{"n":292,"w":"exaggerate","lvl":"Advanced","tier":"Advanced Challenge","pos":"v.","ipa":"/ɪɡˈzædʒəreɪt/","def":"To make something seem greater than it is.","ex":"Do not exaggerate the size of the problem.","es":"exagerar","org":"Latin","ety":"Latin 'exaggerare', to heap up, from 'agger' (a mound of earth).","triv":"The Romans pictured exaggeration as piling dirt higher and higher.","trap":"One X, double G: exa-GG-erate.","esn":"Español una G; el inglés dobla: exaGGerate."},{"n":293,"w":"feasibility","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˌfizəˈbɪləti/","def":"How practical or possible something is.","ex":"The study will assess the project's feasibility.","es":"viabilidad / factibilidad","org":"French","ety":"Old French 'faisable', doable, from 'faire' (to do), from Latin 'facere'.","triv":"Fact, factory and feasibility all come from that Latin 'to do'.","trap":"FEAS- at the front, then -IBILITY: fea-S-ibility.","esn":""},{"n":294,"w":"fluorescent","lvl":"Advanced","tier":"Advanced Challenge","pos":"adj.","ipa":"/flʊˈrɛsənt/","def":"Producing a bright glow under certain light.","ex":"The fluorescent paint glowed under ultraviolet light.","es":"fluorescente","org":"Latin","ety":"Named in 1852 from fluorspar, the mineral that glows, from Latin 'fluere' (to flow).","triv":"Fluorine, fluid and fluorescent all flow from that verb.","trap":"FLUO-, not 'FLOU-': fl-U-orescent. Then -SCENT.","esn":"El orden es U antes de O: flUOrescent."},{"n":295,"w":"hierarchy","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˈhaɪərɑrki/","def":"A system organized into levels of importance.","ex":"The chart shows the company's hierarchy.","es":"jerarquía","org":"Greek","ety":"Greek 'hierarkhes', a high priest, from 'hieros' (sacred) plus 'arkhein' (to rule).","triv":"It first described the ranks of angels, long before it described offices.","trap":"HIER- at the front and -ARCHY at the end, with the CH: hier-ARCH-y.","esn":"Empieza con H muda y lleva CH: HIERarCHy."},{"n":296,"w":"hypothesis","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/haɪˈpɑθəsɪs/","def":"A proposed explanation that can be tested.","ex":"The experiment supported our hypothesis.","es":"hipótesis","org":"Greek","ety":"Greek 'hypothesis', a placing under, from 'hypo' (under) plus 'thesis' (a placing) - the foundation you argue from.","triv":"Plural the Greek way: one hypothesis, two hypotheses.","trap":"HY- at the front with a Y, then -POTHESIS.","esn":"Plural irregular: hypothesis -> hypotheses."},{"n":297,"w":"implementation","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˌɪmpləmɛnˈteɪʃən/","def":"The process of putting a plan into action.","ex":"Implementation of the new system begins Monday.","es":"implementación / puesta en marcha","org":"Latin","ety":"Late Latin 'implementum', a filling up, from 'implere' (to fill). An implement was a tool that filled a need.","triv":"It was a noun for tools for centuries before software borrowed it as a verb.","trap":"-PLEMENT- in the middle: im-PLE-MENT-ation.","esn":""},{"n":298,"w":"incompatible","lvl":"Advanced","tier":"Advanced Challenge","pos":"adj.","ipa":"/ˌɪnkəmˈpætəbəl/","def":"Unable to work or exist well together.","ex":"The file is incompatible with this software.","es":"incompatible","org":"Latin","ety":"Medieval Latin 'incompatibilis', from 'compati' - to suffer with, the same root as compassion.","triv":"Things that cannot suffer each other's company, quite literally.","trap":"-IBLE, not -ABLE: incompat-IBLE.","esn":""},{"n":299,"w":"infrastructure","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˈɪnfrəˌstrʌktʃɚ/","def":"Basic systems such as roads and water supplies.","ex":"The city needs better transport infrastructure.","es":"infraestructura","org":"Latin","ety":"Latin 'infra' (below) plus 'structura' (a building) - coined in French for the groundwork of a railway.","triv":"NATO carried the word into English in the 1950s, and it never left.","trap":"INFRA- with one A, then -STRUCTURE.","esn":"Español 'infraEstructura' con E; el inglés no la lleva: infrAstructure."},{"n":300,"w":"innovation","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˌɪnəˈveɪʃən/","def":"The introduction of new ideas or methods.","ex":"The company encourages innovation in teaching.","es":"innovación","org":"Latin","ety":"Latin 'innovare', to renew, from 'novus' (new).","triv":"For most of its life the word was an insult: an innovator was a dangerous meddler.","trap":"Double N at the front: i-NN-ovation.","esn":"Español una N; el inglés dobla: iNNovation."},{"n":301,"w":"insightful","lvl":"Advanced","tier":"Advanced Challenge","pos":"adj.","ipa":"/ˈɪnsaɪtfəl/","def":"Showing a deep understanding of something.","ex":"She asked an insightful question about the results.","es":"perspicaz","org":"Old English","ety":"'Insight' is 'in' plus 'sight', a Middle English compound meaning inner sight.","triv":"Despite sounding scholarly, it is one of the plainest Germanic words on this list.","trap":"The silent GH of sight, then -FUL with ONE L.","esn":"El sufijo -FUL lleva una sola L."},{"n":302,"w":"integrity","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ɪnˈtɛɡrəti/","def":"The quality of being honest and principled.","ex":"A good leader acts with integrity.","es":"integridad","org":"Latin","ety":"Latin 'integritas', wholeness, from 'integer' (untouched, whole).","triv":"The whole numbers in mathematics are integers for exactly the same reason.","trap":"-EGRITY at the end: int-E-grity, not 'intergrity'.","esn":""},{"n":303,"w":"interference","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˌɪntɚˈfɪrəns/","def":"Unwanted involvement that disrupts something.","ex":"The team completed the work without outside interference.","es":"interferencia","org":"Latin","ety":"Latin 'inter' (between) plus 'ferire' (to strike) - a striking between.","triv":"Radio interference gave the word its technical life in the 1900s.","trap":"-FERENCE at the end, like difference and reference.","esn":""},{"n":304,"w":"legitimate","lvl":"Advanced","tier":"Advanced Challenge","pos":"adj.","ipa":"/lɪˈdʒɪtəmət/","def":"Reasonable and acceptable.","ex":"Parents raised legitimate concerns about safety.","es":"legítimo","org":"Latin","ety":"Latin 'legitimus', lawful, from 'lex' (law).","triv":"Legal, legislate and legitimate all come from that same law.","trap":"-TIMATE at the end: legi-TIMATE, with an I, not an E.","esn":""},{"n":305,"w":"maintenance","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˈmeɪntənəns/","def":"Work done to keep something in good condition.","ex":"The equipment requires regular maintenance.","es":"mantenimiento","org":"Latin","ety":"Latin 'manu tenere', to hold in the hand, which became Old French 'maintenir' and then the English pair maintain / maintenance.","triv":"The verb kept the AI (maintain) but the noun did not: maintenance.","trap":"maintAIN but maintEnance. The noun drops the I and takes an E.","esn":"El verbo lleva AI (maintain); el sustantivo lleva E (maintEnance)."},{"n":306,"w":"meticulous","lvl":"Advanced","tier":"Advanced Challenge","pos":"adj.","ipa":"/məˈtɪkjələs/","def":"Extremely careful about every small detail.","ex":"She kept meticulous records of every payment.","es":"meticuloso","org":"Latin","ety":"Latin 'meticulosus', fearful, from 'metus' (fear) - the careful person was originally the frightened one.","triv":"It was a term of mild abuse in the 1800s before it became a compliment.","trap":"-ICULOUS at the end: met-I-culous.","esn":""},{"n":307,"w":"negligence","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˈnɛɡlɪdʒəns/","def":"Failure to take proper care.","ex":"The damage resulted from negligence.","es":"negligencia / descuido","org":"Latin","ety":"Latin 'negligere', to disregard, from 'neg-' (not) plus 'legere' (to pick up).","triv":"Not picking things up is still exactly what negligence means in court.","trap":"-GLIGENCE with a G: ne-G-li-G-ence, then -ENCE.","esn":""},{"n":308,"w":"nevertheless","lvl":"Advanced","tier":"Advanced Challenge","pos":"adv.","ipa":"/ˌnɛvɚðəˈlɛs/","def":"Despite what has just been said.","ex":"The task was difficult; nevertheless, we finished it.","es":"sin embargo","org":"Old English","ety":"Three Old English words run together: never the less.","triv":"English kept the three-word version too, but only inside the phrase 'none the less'.","trap":"One word, three parts: NEVER + THE + LESS. Double S at the end.","esn":""},{"n":309,"w":"occurrence","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/əˈkɝəns/","def":"Something that happens.","ex":"Heavy snow is a rare occurrence here.","es":"suceso / aparición","org":"Latin","ety":"Latin 'occurrere', to run toward or meet, from 'currere' (to run).","triv":"Current, courier and occurrence all run from that verb.","trap":"Double C and double R, then -ENCE: o-CC-u-RR-ence.","esn":"Dos C y dos R. Y termina en -ENCE, no -ANCE."},{"n":310,"w":"perseverance","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˌpɝsəˈvɪrəns/","def":"Continued effort despite problems or difficulty.","ex":"Her perseverance helped her master the difficult piece.","es":"perseverancia","org":"Latin","ety":"Latin 'perseverare', to persist, from 'severus' (strict, serious).","triv":"The NASA rover Perseverance landed on Mars in 2021 carrying the word to another planet.","trap":"-ANCE at the end, not -ENCE, and no double R: per-SE-VER-ance.","esn":""},{"n":311,"w":"phenomenon","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/fəˈnɑməˌnɑn/","def":"An event or fact that can be observed.","ex":"Scientists are studying this unusual phenomenon.","es":"fenómeno","org":"Greek","ety":"Greek 'phainomenon', a thing appearing, from 'phainein' (to show).","triv":"Plural the Greek way: one phenomenon, several phenomena.","trap":"PH at the front, then -OMENON with three O's... and never 'phenomenom'.","esn":"Plural irregular: phenomenon -> phenomena. Y el /f/ va con PH."},{"n":312,"w":"prejudice","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˈprɛdʒədɪs/","def":"An unfair opinion formed without enough knowledge.","ex":"Education can help reduce prejudice.","es":"prejuicio","org":"French","ety":"Old French 'prejudice', from Latin 'praejudicium' - a judgement made beforehand.","triv":"In law it still means damage: 'without prejudice' protects your rights.","trap":"-JUDICE at the end: preju-DICE, with the word 'dice' in it.","esn":""},{"n":313,"w":"privilege","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˈprɪvəlɪdʒ/","def":"A special right or advantage.","ex":"Access to the private library is a privilege.","es":"privilegio","org":"Latin","ety":"Latin 'privilegium', a law ('lex') for one private person ('privus').","triv":"It began as a law made for a single individual - which is exactly the complaint people make about privilege now.","trap":"No D anywhere: pri-VI-LEGE. Four vowels, all of them E or I.","esn":"Ni una D. El error común es escribir 'priviledge'."},{"n":314,"w":"reconciliation","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˌrɛkənsɪliˈeɪʃən/","def":"The restoration of a friendly relationship.","ex":"The meeting was a first step toward reconciliation.","es":"reconciliación","org":"Latin","ety":"Latin 'reconciliare', to bring together again, from 'concilium' (a council or meeting).","triv":"Council and reconciliation are the same gathering.","trap":"-CILIATION at the end: recon-CIL-i-ation.","esn":""},{"n":315,"w":"resilience","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/rɪˈzɪliəns/","def":"The ability to recover after difficulty.","ex":"The community showed resilience after the storm.","es":"resiliencia / capacidad de recuperación","org":"Latin","ety":"Latin 'resilire', to leap back, from 'salire' (to jump).","triv":"Salmon may be named from that same leaping verb.","trap":"-ENCE at the end, and one L: resi-L-ience.","esn":""},{"n":316,"w":"scrutiny","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˈskrutəni/","def":"Close and careful examination.","ex":"The proposal came under public scrutiny.","es":"escrutinio / examen minucioso","org":"Latin","ety":"Latin 'scrutinium', from 'scrutari' - to search through rubbish, from 'scruta' (trash).","triv":"Close examination was, to the Romans, literally rummaging through the rags.","trap":"SCRU- at the front, then -TINY, which is the whole word 'tiny'.","esn":"En español lleva E inicial ('escrutinio'); en inglés no: Scrutiny."},{"n":317,"w":"simultaneous","lvl":"Advanced","tier":"Advanced Challenge","pos":"adj.","ipa":"/ˌsaɪməlˈteɪniəs/","def":"Happening at the same time.","ex":"The festival held simultaneous events in two halls.","es":"simultáneo","org":"Latin","ety":"Latin 'simul' (at the same time), shaped by 'instantaneous'.","triv":"'Simulate' and 'assemble' come from that same 'simul'.","trap":"-ULTANEOUS at the end: sim-UL-ta-NE-OUS.","esn":""},{"n":318,"w":"sophisticated","lvl":"Advanced","tier":"Advanced Challenge","pos":"adj.","ipa":"/səˈfɪstɪkeɪtɪd/","def":"Advanced and complex in design or operation.","ex":"The laboratory uses sophisticated equipment.","es":"sofisticado","org":"Greek","ety":"Greek 'sophistes', a wise man or teacher, from 'sophia' (wisdom), through Latin.","triv":"It meant 'adulterated, corrupted' for 400 years; the flattering sense is only a century old.","trap":"PH for the /f/ sound: so-PH-isticated.","esn":"El /f/ se escribe PH: sofisticado -> soPHisticated."},{"n":319,"w":"sustainability","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/səˌsteɪnəˈbɪləti/","def":"Using resources so they remain available in the future.","ex":"The school promotes sustainability by reducing waste.","es":"sostenibilidad","org":"French","ety":"Old French 'sustenir', from Latin 'sustinere' - to hold up from below.","triv":"The environmental sense dates from a 1987 United Nations report.","trap":"sustAIN keeps the AI all the way through: sust-AIN-ability.","esn":"A diferencia de maintenance, aquí la AI se queda: sustAINability."},{"n":320,"w":"vulnerability","lvl":"Advanced","tier":"Advanced Challenge","pos":"n.","ipa":"/ˌvʌlnərəˈbɪləti/","def":"The state of being easily harmed or damaged.","ex":"Strong passwords reduce your vulnerability to attacks.","es":"vulnerabilidad","org":"Latin","ety":"Latin 'vulnerabilis', woundable, from 'vulnus' (a wound).","triv":"In computing a vulnerability is still exactly that: a place where the system can be wounded.","trap":"-NERA- in the middle: vul-NERA-bility. Say all six syllables.","esn":""}];
